    pricingPlans: [{ name: "Free", price: "\uBB34\uB8CC", features: ["\uAE30\uBCF8 \uC5D0\uC774\uC804\uD2B8", "\uC6F9 \uAC80\uC0C9", "\uC624\uD508\uC18C\uC2A4"], recommended: true }, { name: "Cloud", price: "$20/\uC6D4", features: ["\uD074\uB77C\uC6B0\uB4DC \uC2E4\uD589", "\uC6B0\uC120 \uCC98\uB9AC", "\uACE0\uAE09 \uB3C4\uAD6C"] }],
    longDescription: "AutoGPT\uB294 2023\uB144 3\uC6D4 Significant Gravitas\uAC00 \uACF5\uAC1C\uD55C \uC624\uD508\uC18C\uC2A4 \uC790\uC728 AI \uC5D0\uC774\uC804\uD2B8 \uD504\uB85C\uC81D\uD2B8\uB85C, GitHub \uC5ED\uC0AC\uC0C1 \uAC00\uC7A5 \uBE60\uB978 \uC131\uC7A5\uC744 \uAE30\uB85D\uD558\uBA70 18\uB9CC 5\uCC9C \uAC1C \uC774\uC0C1\uC758 \uC2A4\uD0C0\uB97C \uB2EC\uC131\uD588\uC2B5\uB2C8\uB2E4. \uAE30\uC874 ChatGPT\uAC00 \uC9C8\uBB38\uC5D0 \uC77C\uD68C\uC131 \uC751\uB2F5\uC744 \uC81C\uACF5\uD558\uB294 \uAC83\uACFC \uB2EC\uB9AC, AutoGPT\uB294 \uC0AC\uC6A9\uC790\uAC00 \uC124\uC815\uD55C \uC0C1\uC704 \uBAA9\uD45C\uB97C AI \uC2A4\uC2A4\uB85C \uBD84\uC11D\uD558\uC5EC \uD558\uC704 \uC791\uC5C5\uC73C\uB85C \uBD84\uD574\uD558\uACE0, \uC778\uD130\uB137 \uAC80\uC0C9\xB7\uD30C\uC77C \uC77D\uAE30/\uC4F0\uAE30\xB7\uCF54\uB4DC \uC2E4\uD589\xB7API \uD638\uCD9C \uB4F1 \uB2E4\uC591\uD55C \uB3C4\uAD6C\uB97C \uC790\uC728\uC801\uC73C\uB85C \uD65C\uC6A9\uD574 \uBAA9\uD45C\uB97C \uB2EC\uC131\uD569\uB2C8\uB2E4. \uD604\uC7AC\uB294 AutoGPT Platform\uC73C\uB85C \uC9C4\uD654\uD558\uC5EC \uB178\uCF54\uB4DC \uC5D0\uC774\uC804\uD2B8 \uBE4C\uB354, AutoPilot \uCC44\uD305 \uC778\uD130\uD398\uC774\uC2A4, \uB9C8\uCF13\uD50C\uB808\uC774\uC2A4 \uB4F1 \uC5D4\uD130\uD504\uB77C\uC774\uC988\uAE09 \uAE30\uB2A5\uC744 \uAC16\uCD98 \uC885\uD569 AI \uC5D0\uC774\uC804\uD2B8 \uD50C\uB7AB\uD3FC\uC785\uB2C8\uB2E4.\n\uD575\uC2EC \uAE30\uC220 \uC2A4\uD0DD\uC73C\uB85C GPT-4, Claude, Llama \uB4F1 \uB2E4\uC591\uD55C LLM\uC744 \uC9C0\uC6D0\uD558\uBA70, \uBCA1\uD130 \uB370\uC774\uD130\uBCA0\uC774\uC2A4 \uAE30\uBC18 \uBA54\uBAA8\uB9AC \uC2DC\uC2A4\uD15C, \uBCD1\uB82C \uB3C4\uAD6C \uC2E4\uD589, \uCEE8\uD14D\uC2A4\uD2B8 \uC555\uCD95, \uBA40\uD2F0\uBAA8\uB2EC \uC785\uB825, \uC74C\uC131 \uC785\uCD9C\uB825, \uD074\uB77C\uC6B0\uB4DC \uC0CC\uB4DC\uBC15\uC2A4 \uB4F1 \uAC15\uB825\uD55C \uAE30\uB2A5\uC744 \uC81C\uACF5\uD569\uB2C8\uB2E4. AutoPilot \uAE30\uB2A5\uC740 \uC790\uC5F0\uC5B4\uB85C \uC5D0\uC774\uC804\uD2B8\uB97C \uC0DD\uC131\xB7\uB514\uBC84\uAE45\xB7\uD3B8\uC9D1\uD560 \uC218 \uC788\uB294 \uD601\uC2E0\uC801\uC778 \uC778\uD130\uD398\uC774\uC2A4\uC785\uB2C8\uB2E4. \uC140\uD504\uD638\uC2A4\uD305(\uBB34\uB8CC)\uACFC \uD074\uB77C\uC6B0\uB4DC \uD638\uC2A4\uD305(\uC720\uB8CC)\uC744 \uBAA8\uB450 \uC9C0\uC6D0\uD569\uB2C8\uB2E4.\n2026\uB144 \uD604\uC7AC AutoGPT\uB294 \uC644\uC804\uD55C \uC790\uC728\uC131 \uCE21\uBA74\uC5D0\uC11C\uB294 \uC5EC\uC804\uD788 \uD55C\uACC4\uB97C \uBCF4\uC774\uC9C0\uB9CC, \uBC18\uC790\uC728 \uBAA8\uB4DC\uC5D0\uC11C \uC0AC\uB78C\uC758 \uAC10\uB3C5 \uD558\uC5D0 \uC0AC\uC6A9\uD560 \uB54C \uC5F0\uAD6C \uB9AC\uC11C\uCE58, \uCF54\uB4DC \uC2A4\uCE90\uD3F4\uB529, \uBB38\uC11C \uC0DD\uC131, \uB370\uC774\uD130 \uC218\uC9D1 \uB4F1\uC5D0\uC11C \uC2E4\uC6A9\uC801\uC778 \uAC00\uCE58\uB97C \uC778\uC815\uBC1B\uACE0 \uC788\uC2B5\uB2C8\uB2E4. \uD65C\uBC1C\uD55C \uC624\uD508\uC18C\uC2A4 \uCEE4\uBBA4\uB2C8\uD2F0\uC640 \uBC29\uB300\uD55C \uD1B5\uD569 \uB77C\uC774\uBE0C\uB7EC\uB9AC\uB294 AutoGPT\uC758 \uAC00\uC7A5 \uD070 \uACBD\uC7C1\uB825\uC785\uB2C8\uB2E4.",
    pros: ["\uC790\uC728 \uACC4\uD68D \uC218\uB9BD \uBC0F \uC2E4\uD589 \u2014 \uBAA9\uD45C\uB9CC \uC124\uC815\uD558\uBA74 AI\uAC00 \uC2A4\uC2A4\uB85C \uC791\uC5C5\uC744 \uBD84\uD574\uD558\uACE0 \uC21C\uCC28\uC801\uC73C\uB85C \uC2E4\uD589", "\uD48D\uBD80\uD55C \uC624\uD508\uC18C\uC2A4 \uC0DD\uD0DC\uACC4 \u2014 18\uB9CC 5\uCC9C \uAC1C GitHub \uC2A4\uD0C0, \uB2E4\uC591\uD55C \uD50C\uB7EC\uADF8\uC778\uACFC \uD1B5\uD569 \uB77C\uC774\uBE0C\uB7EC\uB9AC", "\uB2E4\uC591\uD55C LLM \uC9C0\uC6D0 \u2014 GPT-4, Claude, Llama \uB4F1 \uC5EC\uB7EC \uBAA8\uB378\uC744 \uD544\uC694\uC640 \uC608\uC0B0\uC5D0 \uB9DE\uAC8C \uC120\uD0DD \uAC00\uB2A5"],
