    useCases: ["\uBCF5\uC7A1\uD55C \uBB38\uC81C \uD574\uACB0 \u2014 \uC5EC\uB7EC AI\uAC00 \uC5ED\uD560\uC744 \uB098\uB220 \uD611\uB825\uD558\uC5EC \uBCF5\uC7A1\uD55C \uBB38\uC81C \uBD84\uC11D \uBC0F \uD574\uACB0", "\uCF54\uB4DC \uC0DD\uC131 \uBC0F \uB9AC\uBDF0 \u2014 \uCF54\uB529 \uC5D0\uC774\uC804\uD2B8\uC640 \uB9AC\uBDF0 \uC5D0\uC774\uC804\uD2B8\uAC00 \uD611\uC5C5\uD558\uC5EC \uCF54\uB4DC \uD488\uC9C8 \uD5A5\uC0C1", "\uB370\uC774\uD130 \uBD84\uC11D \uD30C\uC774\uD504\uB77C\uC778 \u2014 \uB370\uC774\uD130 \uC218\uC9D1\u2192\uBD84\uC11D\u2192\uC2DC\uAC01\uD654 \uC5D0\uC774\uC804\uD2B8\uAC00 \uC21C\uCC28\uC801 \uD611\uC5C5", "\uC5F0\uAD6C \uB9AC\uC11C\uCE58 \u2014 \uBB38\uD5CC \uAC80\uC0C9\u2192\uC694\uC57D\u2192\uBCF4\uACE0\uC11C \uC791\uC131 \uC5D0\uC774\uC804\uD2B8\uB85C \uAD6C\uC131\uB41C \uC5F0\uAD6C \uBCF4\uC870 \uC2DC\uC2A4\uD15C", "\uAD50\uC721 \uD29C\uD130\uB9C1 \u2014 \uD559\uC0DD \uBAA8\uB378\uB9C1\u2192\uB9DE\uCDA4 \uC124\uBA85\u2192\uBB38\uC81C \uC0DD\uC131 \uC5D0\uC774\uC804\uD2B8\uAC00 \uD611\uB825\uD558\uB294 AI \uD29C\uD130"],
